CREATE TABLE public.institution_signed_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES public.institutions(id),kind text NOT NULL CHECK(kind IN ('grades','order')),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),body text NOT NULL DEFAULT '',holder text NOT NULL DEFAULT '',grades jsonb NOT NULL DEFAULT '[]',issued_by uuid NOT NULL,signer_name text NOT NULL,signer_role text NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),verification_hash text NOT NULL UNIQUE,verification_payload text NOT NULL);
GRANT SELECT ON public.institution_signed_documents TO authenticated; GRANT ALL ON public.institution_signed_documents TO service_role;
ALTER TABLE public.institution_signed_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY signed_document_read ON public.institution_signed_documents FOR SELECT TO authenticated USING(public.can_manage_student_records(institution_id));
CREATE FUNCTION public.issue_institution_document(_inst uuid,_kind text,_title text,_body text,_holder text,_grades jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE docid uuid:=gen_random_uuid(); issued timestamptz:=now(); signer text; roletext text; payload text; BEGIN IF NOT public.can_manage_student_records(_inst) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; IF _kind NOT IN ('grades','order') OR length(btrim(_title)) NOT BETWEEN 1 AND 120 OR length(_body)>10000 OR length(_holder)>120 OR jsonb_typeof(_grades)<>'array' OR jsonb_array_length(_grades)>30 THEN RAISE EXCEPTION 'Documento inválido'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(_grades) g WHERE jsonb_typeof(g->'score')<>'number' OR (g->>'score')::numeric NOT BETWEEN 0 AND 100 OR length(coalesce(g->>'subject','')) NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Notas inválidas'; END IF; SELECT display_name INTO signer FROM public.profiles WHERE id=auth.uid(); IF coalesce(btrim(signer),'')='' THEN RAISE EXCEPTION 'Complete su nombre en Perfil antes de emitir'; END IF; roletext:=public.institution_role_of(_inst)::text; payload:=jsonb_build_object('id',docid,'institution',_inst,'kind',_kind,'title',btrim(_title),'body',_body,'holder',_holder,'grades',_grades,'issuer',auth.uid(),'signer',signer,'role',roletext,'date',issued)::text; INSERT INTO public.institution_signed_documents(id,institution_id,kind,title,body,holder,grades,issued_by,signer_name,signer_role,issued_at,verification_hash,verification_payload) VALUES(docid,_inst,_kind,btrim(_title),_body,_holder,_grades,auth.uid(),signer,roletext,issued,encode(digest(payload,'sha256'),'hex'),payload); RETURN docid; END $$;
REVOKE ALL ON FUNCTION public.issue_institution_document(uuid,text,text,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.issue_institution_document(uuid,text,text,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.verify_institution_document(_hash text) RETURNS TABLE(institution_name text,kind text,issued_at timestamptz,valid boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT i.name,d.kind,d.issued_at,encode(digest(d.verification_payload,'sha256'),'hex')=d.verification_hash FROM public.institution_signed_documents d JOIN public.institutions i ON i.id=d.institution_id WHERE d.verification_hash=_hash AND _hash ~ '^[a-f0-9]{64}$' $$;
REVOKE ALL ON FUNCTION public.verify_institution_document(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.verify_institution_document(text) TO anon,authenticated;